import React, { ReactNode, useEffect, useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useCompany } from '../../context/CompanyContext';
import { useAuth } from '../../context/AuthContext';
import { useTheme } from '../../context/ThemeContext';
import { brandColorFor, hexToRgba, relativeLuminance } from '../../utils/colors';
import { exitOrganization } from '../../services/api';
import CompanySelector, { CompanyThumb } from './CompanySelector';
import { QuoteFlowLogo, QuoteFlowMark } from '../common/QuoteFlowLogo';
import DemoBanner from './DemoBanner';
import {
  Home,
  Landmark,
  FileText,
  History,
  Settings,
  Building2,
  Receipt,
  LogOut,
  User,
  UserCog,
  Tags,
  ArchiveRestore,
  Users,
  ShieldCheck,
  PanelLeftClose,
  PanelLeftOpen,
  Truck,
  Briefcase,
  Store,
  ShoppingCart,
  Wallet,
  Banknote,
  Fingerprint,
  FileSignature,
  ClipboardList,
  PackageCheck,
  HandCoins,
  ScrollText,
  HeartHandshake,
  Sun,
  Moon,
} from 'lucide-react';

// Banner-style header logo with cascading fallback so a broken/404 image
// never leaves a blank gap in the header:
//   1) admin-uploaded thumbnail (logo_url) — tried first
//   2) bundled brand logo (quote_logo_url) — fallback if (1) fails to load
//   3) round CompanyThumb (which falls back to initials) — final safety net
const HeaderLogo: React.FC<{ company: NonNullable<ReturnType<typeof useCompany>['selectedCompany']> }> = ({ company }) => {
  // 0 = uploaded thumbnail, 1 = bundled brand logo, 2 = thumb fallback.
  const [stage, setStage] = React.useState(0);
  // Reset to stage 0 whenever the company changes.
  React.useEffect(() => {
    setStage(0);
  }, [company.id]);

  const candidates = React.useMemo(
    () => [company.logo_url, company.quote_logo_url].filter(Boolean) as string[],
    [company.logo_url, company.quote_logo_url]
  );

  if (stage >= candidates.length) {
    return <CompanyThumb company={company} size="lg" />;
  }

  return (
    <img
      key={candidates[stage]}
      src={candidates[stage]}
      alt={`${company.name} logo`}
      className="object-contain max-h-14 w-auto"
      loading="eager"
      decoding="async"
      draggable={false}
      onError={() => setStage((s) => s + 1)}
    />
  );
};

interface LayoutProps {
  children: ReactNode;
}

const Layout: React.FC<LayoutProps> = ({ children }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const { selectedCompany, companies, loading: companiesLoading, createCompany } = useCompany();
  const { user, logout, isAdmin, isSuperAdmin, canManageAttendance, canAccessPayroll, canViewAudit, actingOrganization, isDemo, canUseDeliveryNotes, canHandlePayments } = useAuth();
  const { theme, toggle: toggleTheme } = useTheme();
  const isDark = theme === 'dark';

  // A super-admin who hasn't "entered" an org is in platform mode: they only
  // manage organizations (no company/tenant chrome). Entering an org clears
  // this and scopes the whole app to that tenant (with an "exit" banner).
  const platformMode = isSuperAdmin && !actingOrganization;

  const handleExitOrg = async () => {
    try {
      await exitOrganization();
    } catch { /* ignore */ }
    window.location.assign('/organizations');
  };

  const [collapsed, setCollapsed] = useState<boolean>(
    () => localStorage.getItem('sidebarCollapsed') === 'true'
  );

  // Onboarding: a brand-new organization has no companies yet.
  const [firstCompanyName, setFirstCompanyName] = useState('');
  const [creatingFirst, setCreatingFirst] = useState(false);
  const [firstError, setFirstError] = useState('');

  const handleCreateFirstCompany = async () => {
    if (!firstCompanyName.trim()) { setFirstError('Please enter a company name.'); return; }
    setCreatingFirst(true);
    setFirstError('');
    try {
      await createCompany(firstCompanyName.trim());
      // Company created → CompanyContext reloads → this onboarding disappears.
    } catch (e: any) {
      setFirstError(e?.response?.data?.error || 'Could not create the company.');
    } finally {
      setCreatingFirst(false);
    }
  };

  const toggleCollapsed = () => {
    setCollapsed((prev) => {
      const next = !prev;
      localStorage.setItem('sidebarCollapsed', String(next));
      return next;
    });
  };

  const handleLogout = async () => {
    try {
      await logout();
      navigate('/login');
    } catch (error) {
      console.error('Logout failed:', error);
    }
  };

  // Get the primary color from the selected company or use default
  const primaryColor = selectedCompany?.primary_color || '#4f46e5';
  // Theme-aware version: in dark mode this is the brightened color used for
  // text / icons / borders that need to read against a dark surface. In
  // light mode it's identical to `primaryColor`.
  const accentColor = brandColorFor(primaryColor, isDark);
  // Tint alpha for soft brand backgrounds — bumped a touch in dark mode so
  // the company tint stays visible against the gray-800/900 surface without
  // overpowering the chrome (now that the accent color itself is properly
  // lifted by brandColorFor, the tints don't have to compensate as much).
  // Soft brand tint used for the active nav pill + the user avatar. The sidebar
  // itself stays on the plain theme surface (no brand wash).
  const tintBg = hexToRgba(primaryColor, isDark ? 0.20 : 0.12);

  // Publish the active company's brand color as CSS variables so every generic
  // accent in the app (focus rings, pickers, stat cards, buttons — see the
  // brand-accent block in index.css) automatically matches the current logo,
  // in both light and dark themes.
  useEffect(() => {
    const root = document.documentElement;
    root.style.setProperty('--brand', accentColor);
    root.style.setProperty('--brand-strong', primaryColor);
    root.style.setProperty('--brand-weak', hexToRgba(primaryColor, isDark ? 0.20 : 0.10));
    root.style.setProperty('--brand-on', relativeLuminance(primaryColor) > 0.55 ? '#0f172a' : '#ffffff');
  }, [accentColor, primaryColor, isDark]);

  // In platform mode the only destination is the Organizations page.
  useEffect(() => {
    if (platformMode && location.pathname !== '/organizations' && location.pathname !== '/audit-log') {
      navigate('/organizations', { replace: true });
    }
  }, [platformMode, location.pathname, navigate]);

  // A clean modern nav item: a rounded pill. Active = soft brand-tint fill +
  // brand-coloured text/icon; inactive = muted with a subtle hover. No brand
  // wash on the sidebar itself.
  const getNavItemClass = (path: string) => {
    const base = `group flex items-center ${collapsed ? 'justify-center px-0' : 'space-x-3 px-3'} py-2.5 rounded-lg text-sm font-medium transition-colors`;
    const isActive = location.pathname === path;
    return isActive
      ? `${base} font-semibold`
      : `${base} text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-white/5 hover:text-gray-900 dark:hover:text-white`;
  };

  const getNavItemStyle = (path: string): React.CSSProperties => {
    const isActive = location.pathname === path;
    if (!isActive) return {};
    // Active pill: soft brand fill + brightened brand text/icon (legible on
    // both the light and dark neutral surfaces).
    return { backgroundColor: tintBg, color: accentColor };
  };

  // Grouped navigation — labelled sections make the growing menu easy to scan.
  const navSections: { label?: string; items: { to: string; icon: typeof Home; label: string }[] }[] = platformMode ? [
    { label: 'Platform', items: [
      { to: '/organizations', icon: Building2, label: 'Organizations' },
      { to: '/audit-log', icon: ScrollText, label: 'Audit Log' },
    ] },
  ] : [
    { items: [{ to: '/', icon: Home, label: 'Dashboard' }] },
    { label: 'Create', items: [
      { to: '/new-quotation', icon: FileText, label: 'New Quotation' },
      { to: '/job-cards/new', icon: ClipboardList, label: 'New Job Card' },
      { to: '/new-invoice', icon: Receipt, label: 'New Invoice' },
      ...(canUseDeliveryNotes ? [{ to: '/new-delivery-note', icon: Truck, label: 'New Delivery Note' }] : []),
      { to: '/lpos/new', icon: PackageCheck, label: 'New LPO' },
    ]},
    { label: 'Records', items: [
      { to: '/history', icon: History, label: 'Quotation History' },
      { to: '/job-cards', icon: ClipboardList, label: 'Job Cards' },
      { to: '/services', icon: Tags, label: 'Services & Prices' },
      { to: '/invoice-history', icon: Receipt, label: 'Invoice History' },
      ...(canUseDeliveryNotes ? [{ to: '/delivery-history', icon: Truck, label: 'Delivery Notes' }] : []),
      { to: '/contracts', icon: FileSignature, label: 'Contracts' },
    ]},
    { label: 'Contacts', items: [
      { to: '/clients', icon: Briefcase, label: 'Clients' },
      { to: '/vendors', icon: Store, label: 'Vendors' },
    ]},
    { label: 'Finance', items: [
      ...(isAdmin && canHandlePayments ? [{ to: '/accounts', icon: Landmark, label: 'Bank & Cash' }] : []),
      { to: '/lpos', icon: PackageCheck, label: 'LPOs' },
      { to: '/purchases', icon: ShoppingCart, label: 'Purchases' },
      { to: '/expenses', icon: Wallet, label: 'Expenses' },
      { to: '/petty-cash', icon: Banknote, label: 'Petty Cash' },
      { to: '/donations', icon: HeartHandshake, label: 'Donations' },
    ]},
    // Attendance is visible to admins AND to any staff granted attendance access.
    ...(canManageAttendance && !isAdmin ? [{ label: 'Attendance', items: [
      { to: '/attendance', icon: Fingerprint, label: 'Attendance' },
    ]}] : []),
    ...(isAdmin ? [{ label: 'Admin', items: [
      { to: '/attendance', icon: Fingerprint, label: 'Attendance' },
      ...(canAccessPayroll ? [{ to: '/payroll', icon: HandCoins, label: 'Payroll' }] : []),
      { to: '/users', icon: Users, label: 'User Management' },
      { to: '/recycle-bin', icon: ArchiveRestore, label: 'Recently Deleted' },
      { to: '/settings', icon: Settings, label: 'Company Settings' },
      ...(canViewAudit ? [{ to: '/audit-log', icon: ScrollText, label: 'Audit Log' }] : []),
    ]}] : []),
    // Audit access granted to a non-admin (rare) still gets a menu entry.
    ...(canViewAudit && !isAdmin ? [{ label: 'Security', items: [
      { to: '/audit-log', icon: ScrollText, label: 'Audit Log' },
    ]}] : []),
    ...(isSuperAdmin ? [{ label: 'Platform', items: [
      { to: '/organizations', icon: Building2, label: 'Organizations' },
    ]}] : []),
  ];

  // Brand-new organization (no companies yet) → a focused onboarding screen
  // instead of the normal app shell, which requires a selected company.
  if (!companiesLoading && companies.length === 0 && !platformMode) {
    return (
      <div className="min-h-screen bg-gray-50 dark:bg-[#121212] flex flex-col transition-colors">
        <header className="flex items-center justify-between px-6 py-4">
          <QuoteFlowLogo size={36} textClassName="text-lg" />
          <div className="flex items-center gap-3">
            <button onClick={toggleTheme} className="inline-flex items-center justify-center h-10 w-10 rounded-full border border-gray-200 dark:border-[#2e2e2e] bg-white dark:bg-[#1e1e1e] text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-white/5 transition-colors" aria-label="Toggle theme">
              {isDark ? <Sun className="h-5 w-5 text-amber-400" /> : <Moon className="h-5 w-5 text-slate-700" />}
            </button>
            <button onClick={handleLogout} className="inline-flex items-center px-3 py-2 text-sm rounded-lg text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-white/5">
              <LogOut className="h-4 w-4 mr-1.5" /> Sign Out
            </button>
          </div>
        </header>

        <div className="flex-1 flex items-center justify-center px-4">
          <div className="w-full max-w-md bg-white dark:bg-[#1e1e1e] rounded-2xl shadow-sm border border-gray-200 dark:border-[#2e2e2e] p-8 text-center">
            <div className="w-14 h-14 rounded-2xl mx-auto flex items-center justify-center mb-4" style={{ backgroundColor: tintBg }}>
              <Building2 className="h-7 w-7" style={{ color: accentColor }} />
            </div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Welcome, {user?.name?.split(' ')[0] || 'there'}!</h1>

            {isAdmin ? (
              <>
                <p className="text-gray-600 dark:text-gray-400 mt-2 mb-6">
                  Let's set up your first company to start creating quotations, invoices and more.
                </p>
                {firstError && (
                  <div className="mb-3 p-3 bg-red-50 border border-red-200 rounded-lg text-red-600 text-sm text-left">{firstError}</div>
                )}
                <input
                  type="text"
                  value={firstCompanyName}
                  onChange={(e) => setFirstCompanyName(e.target.value)}
                  onKeyDown={(e) => { if (e.key === 'Enter') handleCreateFirstCompany(); }}
                  placeholder="Your company name"
                  className="w-full px-4 py-2.5 border border-gray-300 dark:border-[#2e2e2e] rounded-lg mb-3 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                  autoFocus
                />
                <button
                  onClick={handleCreateFirstCompany}
                  disabled={creatingFirst}
                  className="w-full inline-flex items-center justify-center px-4 py-2.5 rounded-lg text-white font-medium shadow-sm hover:opacity-90 disabled:opacity-50"
                  style={{ backgroundColor: accentColor }}
                >
                  {creatingFirst ? 'Creating…' : 'Create company'}
                </button>
                <p className="text-xs text-gray-400 mt-3">You can add more companies and customize details later in Company Settings.</p>
              </>
            ) : (
              <p className="text-gray-600 dark:text-gray-400 mt-2">
                Your organization doesn't have a company set up yet. Please ask your administrator to create one.
              </p>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-[#121212] transition-colors">
      <div className="flex">
        <div
          className={`${collapsed ? 'w-20' : 'w-64'} sticky top-0 h-screen self-start shrink-0 border-r border-gray-200 dark:border-[#2e2e2e] bg-white dark:bg-[#1e1e1e] transition-all duration-300 no-print`}
        >
          <div className={`flex flex-col h-full ${collapsed ? 'p-3' : 'px-4 py-6'}`}>
            {/* Brand + collapse toggle */}
            <div className={`flex items-center mb-6 ${collapsed ? 'justify-center' : 'justify-between px-1'}`}>
              {!collapsed && (
                <div className="flex items-center space-x-2.5 min-w-0">
                  <QuoteFlowMark size={36} />
                  <div className="min-w-0">
                    <h1 className="text-[16px] font-bold tracking-tight text-gray-900 dark:text-white truncate leading-tight">
                      Quote<span className="bg-gradient-to-r from-indigo-600 to-cyan-500 bg-clip-text text-transparent dark:from-indigo-400 dark:to-cyan-300">Flow</span>
                    </h1>
                    <p className="text-[11px] text-gray-500 dark:text-gray-400 truncate">by Orbital IT Solutions</p>
                  </div>
                </div>
              )}
              <button
                onClick={toggleCollapsed}
                className="p-2 rounded-lg text-gray-500 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5 transition-colors flex-shrink-0"
                title={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
                aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
              >
                {collapsed ? <PanelLeftOpen className="h-5 w-5" /> : <PanelLeftClose className="h-5 w-5" />}
              </button>
            </div>

            {!platformMode && <CompanySelector collapsed={collapsed} />}

            {/* The nav is the only scrollable area so the brand stays at the
                top and the user/logout block stays at the bottom even on
                short viewports. `min-h-0` is required for `overflow-y-auto`
                to actually engage inside a flex column. */}
            <nav className="mt-6 flex-1 min-h-0 overflow-y-auto space-y-4 pr-1 -mr-1">
              {navSections.map((section, si) => (
                <div key={si} className="space-y-1">
                  {!collapsed && section.label && (
                    <p className="px-3 pt-1 pb-0.5 text-[11px] font-semibold uppercase tracking-wider text-gray-400 dark:text-gray-500">
                      {section.label}
                    </p>
                  )}
                  {collapsed && si > 0 && (
                    <div className="mx-2 my-2 border-t border-gray-200 dark:border-[#2e2e2e]" />
                  )}
                  {section.items.map(({ to, icon: Icon, label }) => (
                    <Link
                      key={to}
                      to={to}
                      className={getNavItemClass(to)}
                      style={getNavItemStyle(to)}
                      title={collapsed ? label : undefined}
                    >
                      <Icon className="h-5 w-5 flex-shrink-0" />
                      {!collapsed && <span className="truncate">{label}</span>}
                    </Link>
                  ))}
                </div>
              ))}
            </nav>

            {/* User Info & Logout — pinned to bottom of the sidebar via mt-auto */}
            <div className="mt-auto pt-4 border-t border-gray-200 dark:border-[#2e2e2e]">
              {collapsed ? (
                <Link
                  to="/profile"
                  className="mb-2 flex justify-center"
                  title={`${user?.name} (${user?.role}) — My profile`}
                >
                  <div
                    className="w-9 h-9 rounded-full flex items-center justify-center flex-shrink-0"
                    style={{ backgroundColor: tintBg }}
                  >
                    <User className="h-4 w-4" style={{ color: accentColor }} />
                  </div>
                </Link>
              ) : (
                <Link
                  to="/profile"
                  title="My profile: change your name, email or password"
                  className="mb-2 flex items-center space-x-3 px-3 py-2.5 rounded-lg bg-gray-50 dark:bg-white/5 hover:bg-gray-100 dark:hover:bg-white/10 transition-colors"
                >
                  <div
                    className="w-9 h-9 rounded-full flex items-center justify-center flex-shrink-0"
                    style={{ backgroundColor: tintBg }}
                  >
                    <User className="h-4 w-4" style={{ color: accentColor }} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between gap-2">
                      <p className="text-sm font-semibold text-gray-900 dark:text-gray-100 truncate" title={user?.name}>
                        {user?.name}
                      </p>
                      <span
                        className={`inline-flex items-center text-[10px] font-bold uppercase tracking-wide px-1.5 py-0.5 rounded-full flex-shrink-0 ${
                          isAdmin
                            ? 'bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300'
                            : 'bg-gray-100 text-gray-600 dark:bg-neutral-700 dark:text-gray-200'
                        }`}
                      >
                        {isAdmin && <ShieldCheck className="h-3 w-3 mr-0.5" />}
                        {user?.role}
                      </span>
                    </div>
                    <p className="text-xs text-gray-500 dark:text-gray-400 truncate" title={user?.email}>
                      {user?.email}
                    </p>
                  </div>
                </Link>
              )}
              <Link
                to="/profile"
                className={`flex items-center ${collapsed ? 'justify-center px-0' : 'space-x-3 px-3'} py-2.5 rounded-lg transition-colors w-full ${
                  location.pathname === '/profile'
                    ? 'bg-gray-100 text-gray-900 dark:bg-white/10 dark:text-white'
                    : 'text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-white/5'
                }`}
                title={collapsed ? 'My Profile' : undefined}
              >
                <UserCog className="h-5 w-5 flex-shrink-0" />
                {!collapsed && <span className="font-medium">My Profile</span>}
              </Link>
              <button
                onClick={handleLogout}
                className={`flex items-center ${collapsed ? 'justify-center px-0' : 'space-x-3 px-3'} py-2.5 rounded-lg transition-colors text-gray-600 dark:text-gray-300 hover:bg-red-50 hover:text-red-600 dark:hover:bg-red-500/15 dark:hover:text-red-400 w-full`}
                title={collapsed ? 'Sign Out' : undefined}
              >
                <LogOut className="h-5 w-5 flex-shrink-0" />
                {!collapsed && <span className="font-medium">Sign Out</span>}
              </button>
            </div>
          </div>
        </div>

        <div className="flex-1 min-w-0">
          {isDemo && <DemoBanner onExit={handleLogout} />}
          {actingOrganization && (
            <div className="no-print bg-amber-500 text-white px-6 py-2 flex items-center justify-between gap-3 text-sm">
              <span className="flex items-center min-w-0">
                <ShieldCheck className="h-4 w-4 mr-2 flex-shrink-0" />
                <span className="truncate">
                  Viewing <strong>{actingOrganization.name}</strong> as platform admin — any changes affect this organization.
                </span>
              </span>
              <button onClick={handleExitOrg} className="inline-flex items-center px-3 py-1 rounded-md bg-white/20 hover:bg-white/30 font-medium flex-shrink-0">
                <LogOut className="h-4 w-4 mr-1.5" /> Exit
              </button>
            </div>
          )}
          <header className="bg-white dark:bg-[#1e1e1e] border-b border-gray-200 dark:border-[#2e2e2e] px-6 py-4 no-print transition-colors">
            <div className="flex items-center justify-between gap-4">
              <div className="min-w-0">
                <h2 className="text-2xl font-semibold text-gray-900 dark:text-gray-100 truncate">
                  {platformMode ? 'Platform Administration' : (selectedCompany?.name || 'Loading...')}
                </h2>
                <p className="text-sm text-gray-600 dark:text-gray-400 truncate">
                  {platformMode ? 'Manage organizations (tenants)' : selectedCompany?.address}
                </p>
              </div>
              <div className="flex items-center gap-3 flex-shrink-0">
                <button
                  onClick={toggleTheme}
                  className="inline-flex items-center justify-center h-10 w-10 rounded-full border border-gray-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-neutral-800 transition-colors"
                  title={isDark ? 'Switch to light mode' : 'Switch to dark mode'}
                  aria-label={isDark ? 'Switch to light mode' : 'Switch to dark mode'}
                >
                  {isDark
                    ? <Sun className="h-5 w-5 text-amber-400" />
                    : <Moon className="h-5 w-5 text-slate-700" />}
                </button>
                {selectedCompany && <HeaderLogo company={selectedCompany} />}
              </div>
            </div>
          </header>

          <main className="p-6 text-gray-900 dark:text-gray-100 transition-colors">
            {children}
          </main>
        </div>
      </div>
    </div>
  );
};

export default Layout;
